// The engine writes { server, allowInsecureSsl } into the metadata table at
// clone time (key: bitbucket_server-config:{workflow_id}). Derive the bare
// hostname for the /repos?host= filter from the server base URL.
const cfg = $input.first().json.value;
if (!cfg || !cfg.server) {
  // Throwing routes to the shared error handler -> ingestion_errors, instead of
  // silently polling nothing forever.
  throw new Error('bitbucket_server config missing for this workflow - reconnect the Bitbucket Server integration');
}
const server = cfg.server.replace(/\/+$/, '');
const host = server.replace(/^https?:\/\//, '').split('/')[0].split(':')[0];
// Opt-in from the connection form for servers with internal-CA/self-signed
// certs; feeds allowUnauthorizedCerts on the Bitbucket API nodes below.
const allowInsecureSsl = cfg.allowInsecureSsl === true;
return [{ json: { server, host, allowInsecureSsl } }];

const repos = $input.first().json.repos ?? [];
const server = $('Prepare Config').first().json.server;
// Host filtering happens server-side (GET /repos?host=...), so every repo here
// lives on this connection's Bitbucket Server. remote_id is "PROJECT/repo-slug"
// as parsed from the on-prem clone URL.
return repos
  .filter(r => r.remote_id && r.remote_id.includes('/'))
  .map(r => {
    const [project, repo] = r.remote_id.split('/');
    return { json: { project, repo, name: r.name, server } };
  });

// Collect PRs whose activities are worth scanning. The Server list API has no
// updated-since query, and — verified against a live instance — comments and
// approvals DO NOT bump a PR's updatedDate on Server/DC (unlike Cloud), so a
// window test on updatedDate alone silently misses them. Scan activities for:
// PRs updated inside the poll window (state changes), every OPEN PR (live
// review traffic), and recently-closed PRs (post-merge comments). Classify
// Change decides per PR whether anything actually happened; the Has Change
// gate drops the quiet ones so idle polls emit nothing.
// Server timestamps are epoch milliseconds.
const prItems = [];
const now = Date.now();
const since = now - 150000;
const RECENT_CLOSED_MS = 7 * 24 * 3600 * 1000;
for (const item of $input.all()) {
  const prs = item.json.values || [];
  for (const pr of prs) {
    const repo = pr.toRef && pr.toRef.repository;
    const repoSlug = repo ? ((repo.project && repo.project.key) || '') + '/' + (repo.slug || '') : '';
    if (!repoSlug || repoSlug === '/') continue;
    const updated = pr.updatedDate || 0;
    const open = (pr.state || '').toUpperCase() === 'OPEN';
    if (updated < since && !open && updated < now - RECENT_CLOSED_MS) continue;
    prItems.push({ json: { pr, repoSlug } });
  }
}
return prItems.length ? prItems : [{ json: { _skip: true } }];

// Wrap the activities response so it doesn't overwrite PR data on merge.
return $input.all().map(item => ({
  json: { _activity: item.json.values || [] }
}));

// Classify what changed on this PR inside the poll window, from the Server
// activities feed. Server/DC quirks this must handle (all verified against a
// live instance):
// - comments and approvals DO NOT bump pr.updatedDate (unlike Cloud), so
//   Extract PRs passes through every open PR and this code decides from
//   activities alone;
// - replies DO NOT get their own COMMENTED activity - they nest (recursively)
//   under the parent comment's activity, which keeps the parent's timestamp,
//   so every comment thread must be walked;
// - the activities feed is NOT strictly newest-first (comment entries are
//   thread-anchored), so "first matching entry" picks stale data - collect ALL
//   in-window candidates and choose by significance, newest first.
// Events are stamped with the chosen activity's own timestamp (NOT
// pr.updatedDate) so distinct changes get distinct event_ids and the engine's
// event_id dedupe works across overlapping poll windows.
// PRs with nothing in the window come out bb_change_type=no_change_detected
// and are dropped by the Has Change gate downstream.

const POLL_WINDOW_MS = 150000; // 2.5 minutes
const now = Date.now();

const pr = $json.pr;
const repoSlug = $json.repoSlug;
const activity = $json._activity || [];
const reviewers = (pr.reviewers || []).map(rv => rv.user || {});
const state = (pr.state || '').toUpperCase();

// --- Collect in-window change candidates ---
const candidates = [];

function walkThread(node, anchor, parent) {
  if (!node) return;
  if (node.createdDate && (now - node.createdDate) < POLL_WINDOW_MS) {
    candidates.push({ kind: 'COMMENTED', ts: node.createdDate, user: node.author || {}, comment: node, anchor, parent });
  }
  for (const child of (node.comments || [])) walkThread(child, anchor, node);
}

for (const entry of activity) {
  const act = (entry.action || '').toUpperCase();
  if (act === 'COMMENTED') {
    // Walk the whole thread regardless of the entry's own age - a fresh reply
    // hides under an old parent activity.
    walkThread(entry.comment, entry.commentAnchor || null, null);
  } else if (entry.createdDate && (now - entry.createdDate) < POLL_WINDOW_MS) {
    candidates.push({ kind: act, ts: entry.createdDate, user: entry.user || {} });
  }
}

// Most significant change wins; ties broken newest-first. Unlisted actions
// (OPENED, REVIEWED, UNAPPROVED, ...) are dropped.
const PRIORITY = ['MERGED', 'DECLINED', 'REOPENED', 'COMMENTED', 'APPROVED', 'RESCOPED', 'UPDATED'];
const known = candidates.filter(c => PRIORITY.indexOf(c.kind) !== -1);
known.sort((a, b) => {
  const p = PRIORITY.indexOf(a.kind) - PRIORITY.indexOf(b.kind);
  return p !== 0 ? p : b.ts - a.ts;
});
const chosen = known[0];

let rawEventType = 'pr_updated';
let body = '';
let changeType = 'no_change_detected';
let previousState = null;
let newState = null;
let actorName = (pr.author && pr.author.user && pr.author.user.displayName) || 'Unknown';
let actorHandle = (pr.author && pr.author.user && (pr.author.user.name || pr.author.user.slug)) || '';
let actorEmail = (pr.author && pr.author.user && pr.author.user.emailAddress) || '';
let commentId = null;
let eventTs = pr.updatedDate || now;

if (pr.createdDate && (now - pr.createdDate) < POLL_WINDOW_MS) {
  // Brand-new PR
  rawEventType = 'pr_created';
  changeType = 'created';
  body = pr.description || pr.title || '';
  eventTs = pr.createdDate;
} else if (chosen) {
  const user = chosen.user || {};
  actorName = user.displayName || actorName;
  actorHandle = user.name || user.slug || actorHandle;
  actorEmail = user.emailAddress || actorEmail;
  eventTs = chosen.ts;

  if (chosen.kind === 'MERGED') {
    rawEventType = 'pr_merged';
    changeType = 'merged';
    body = 'Pull request merged into ' + ((pr.toRef && pr.toRef.displayId) || 'target branch') + '.';
    previousState = 'OPEN';
    newState = 'MERGED';
  } else if (chosen.kind === 'DECLINED') {
    rawEventType = 'pr_declined';
    changeType = 'declined';
    body = 'Pull request declined.';
    previousState = 'OPEN';
    newState = 'DECLINED';
  } else if (chosen.kind === 'REOPENED') {
    rawEventType = 'pr_reopened';
    changeType = 'reopened';
    body = 'Pull request reopened.';
    newState = 'OPEN';
  } else if (chosen.kind === 'COMMENTED') {
    rawEventType = 'pr_commented';
    changeType = 'commented';
    const commentBody = chosen.comment.text || '';
    if (chosen.comment.id != null) commentId = String(chosen.comment.id);
    if (chosen.parent) {
      // Reply nested in a thread; carry the parent's context into the body so
      // the card reads as a conversation, not a floating remark.
      changeType = 'comment_reply';
      const parentAuthor = (chosen.parent.author && chosen.parent.author.displayName) || 'a comment';
      const parentText = (chosen.parent.text || '').substring(0, 120);
      body = 'Reply from ' + actorName + ' to ' + parentAuthor + ' ("' + parentText + '"):\n' + commentBody;
    } else if (chosen.anchor && chosen.anchor.path) {
      const line = chosen.anchor.line || '';
      body = 'Inline comment on ' + chosen.anchor.path + (line ? ':' + line : '') + ' from ' + actorName + ':\n' + commentBody;
      changeType = 'inline_comment';
    } else {
      body = 'New comment from ' + actorName + ':\n' + commentBody;
    }
  } else if (chosen.kind === 'APPROVED') {
    rawEventType = 'pr_approved';
    changeType = 'approved';
    body = 'Pull request approved by ' + (user.displayName || 'a reviewer') + '.';
  } else if (chosen.kind === 'RESCOPED') {
    rawEventType = 'pr_updated';
    changeType = 'new_commits';
    body = 'New commits pushed to the pull request.';
  } else {
    rawEventType = 'pr_updated';
    changeType = 'fields_updated';
    body = 'PR fields updated.';
  }
} else if ((pr.updatedDate || 0) && (now - pr.updatedDate) < POLL_WINDOW_MS) {
  // updatedDate moved but nothing classifiable in the activities page (e.g.
  // page truncation) - fall back to PR state so merges/declines are never lost.
  if (state === 'MERGED') {
    rawEventType = 'pr_merged';
    changeType = 'merged';
    body = 'Pull request merged into ' + ((pr.toRef && pr.toRef.displayId) || 'target branch') + '.';
  } else if (state === 'DECLINED') {
    rawEventType = 'pr_declined';
    changeType = 'declined';
    body = 'Pull request declined.';
  } else {
    rawEventType = 'pr_updated';
    changeType = 'fields_updated';
    body = 'PR fields updated.';
  }
}
// else: nothing in the window - stays no_change_detected, dropped downstream.

return {
  json: {
    event_id: 'evt_bbs_pr_' + repoSlug.replace('/', '_') + '_' + pr.id + '_' + eventTs,
    timestamp: new Date(eventTs).toISOString(),
    source: {
      platform: 'bitbucket_server',
      connection_id: $workflow.id,
      raw_event_type: rawEventType
    },
    actor: {
      name: actorName,
      email: actorEmail,
      platform_handle: actorHandle
    },
    subject: {
      type: 'pull_request',
      id: repoSlug + '/PR-' + pr.id,
      title: pr.title || '',
      url: (pr.links && pr.links.self && pr.links.self[0] && pr.links.self[0].href) || ''
    },
    content: {
      body: body,
      attachments: [],
      metadata: {
        bb_repository: repoSlug,
        bb_branch: (pr.fromRef && pr.fromRef.displayId) || '',
        bb_target_branch: (pr.toRef && pr.toRef.displayId) || '',
        bb_state: state,
        bb_reviewers: reviewers.map(u => u.displayName || u.name || ''),
        bb_change_type: changeType,
        bb_previous_state: previousState,
        bb_new_state: newState,
        bb_description: pr.description || '',
        bb_comment_id: commentId,
        participants: [
          { role: 'author', name: (pr.author && pr.author.user && pr.author.user.displayName) || '', handle: (pr.author && pr.author.user && (pr.author.user.name || pr.author.user.slug)) || '' },
          ...reviewers.map(u => ({ role: 'reviewer', name: u.displayName || '', handle: u.name || u.slug || '' }))
        ]
      }
    }
  }
};
